import re

with open('references.bib') as f:
    content = f.read()

# Parse entries
entries = {}
pattern = r'@(\w+)\{(\w+),\s*(.*?)\n\}'
for m in re.finditer(pattern, content, re.DOTALL):
    etype = m.group(1)
    key = m.group(2)
    body = m.group(3)
    fields = {}
    for fm in re.finditer(r'(\w+)\s*=\s*\{(.*?)\}', body, re.DOTALL):
        fields[fm.group(1).lower()] = fm.group(2).strip()
    entries[key] = {'type': etype, 'fields': fields}

# Check critical fields
print('=== Entries missing critical fields ===')
for key, e in sorted(entries.items()):
    missing = []
    for f in ['author', 'title', 'year']:
        if f not in e['fields']:
            missing.append(f)
    # Check venue
    has_venue = any(f in e['fields'] for f in ['journal', 'booktitle', 'publisher'])
    if not has_venue:
        missing.append('venue(journal/booktitle/publisher)')
    if missing:
        print(f'  {key} ({e[\"type\"]}): missing {missing}')

print()
print('=== Detailed audit of 6 econometrics entries ===')
targets = ['bound2001measurement', 'frazis2003estimating', 'black2000racial', 
           'mahajan2006identification', 'lewbel2007estimation', 'borkan2019nuanced']
for key in targets:
    if key in entries:
        e = entries[key]
        print(f'\n{key} ({e[\"type\"]}):')
        for fname, fval in sorted(e['fields'].items()):
            print(f'  {fname}: {fval}')
        # Completeness check
        missing = []
        for f in ['author', 'title', 'year']:
            if f not in e['fields']:
                missing.append(f)
        if e['type'] == 'article' and 'journal' not in e['fields']:
            missing.append('journal')
        if e['type'] == 'incollection' and 'booktitle' not in e['fields']:
            missing.append('booktitle')
        if e['type'] == 'inproceedings' and 'booktitle' not in e['fields']:
            missing.append('booktitle')
        if missing:
            print(f'  >>> MISSING: {missing}')
        else:
            print(f'  >>> COMPLETE')
    else:
        print(f'\n{key}: NOT FOUND in .bib')
"

